def run(_context):
    import adsk.core, adsk.fusion, adsk.cam
    app = adsk.core.Application.get()
    doc = app.activeDocument
    cam = adsk.cam.CAM.cast(doc.products.itemByProductType('CAMProductType'))
    setup = cam.setups.item(0)
    camMgr = adsk.cam.CAMManager.get()
    toolLibs = camMgr.libraryManager.toolLibraries
    url = toolLibs.urlByLocation(adsk.cam.LibraryLocations.LocalLibraryLocation)
    for c in toolLibs.childAssetURLs(url):
        if 'TIW' in c.toString():
            lib = toolLibs.toolLibraryAtURL(c); break
    def tool_by_number(n):
        for i in range(lib.count):
            t = lib.item(i)
            if t.parameters.itemByName('tool_number').value.value == n:
                return t
    t_ball = tool_by_number(30)

    inp = setup.operations.createInput('contour3d')
    inp.tool = t_ball
    op = setup.operations.add(inp)
    print("Created", op.name)
    for p in op.parameters:
        if p.name in ('tolerance','maximumStepdown','stepdown','stockToLeave',
                      'steepAngle','minimumCuttingAngle','maximumCuttingAngle'):
            try: print("  ",p.name,"=",p.expression)
            except: pass
    return None

